{
  "items": [
    {
      "title": "Berufliche Schulen in Hessen seit Schuljahr 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Official historical dataset from the Hessian Statistical Office (Hessisches Statistisches Landesamt). Provides longitudinal statistics on vocational schools in Hesse beginning with the 1980/1981 academic year. Particularly relevant for examining changes in vocational education enrollment, school types, and institutional development throughout the 1980s. The landing page provides access to historical tables."
    },
    {
      "title": "Auszubildende und Prüfungen in Hessen seit 1980",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Official statistical time series covering apprentices and vocational examinations in Hesse from 1980 onward. Relevant variables include numbers of apprentices, newly concluded training contracts, prematurely terminated apprenticeships, and examination participants. Particularly useful for studying developments in Germany's dual vocational training system during the 1980s. Available under the section 'Berufliche Bildung in Hessen'."
    },
    {
      "title": "Berufsfachschulen in Hessen seit Schuljahr 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Historical statistics on vocational full-time schools (Berufsfachschulen) in Hesse, beginning in 1980/1981. Useful for analyzing enrollment trends and the development of school-based vocational training during the 1980s. The dataset allows researchers to examine an important alternative or complement to apprenticeship-based vocational education."
    },
    {
      "title": "Berufsschulen (Teilzeitform) in Hessen seit Schuljahr 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Official historical dataset covering part-time vocational schools in Hesse from the 1980/1981 academic year. Particularly relevant because part-time vocational schools constitute the school-based component of Germany's dual vocational education and training system. Useful for analyzing apprenticeship-related schooling and historical changes in vocational participation."
    },
    {
      "title": "Berufsschulen (Vollzeitform) in Hessen seit Schuljahr 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Official time-series statistics on full-time vocational schools in Hesse beginning in 1980/1981. Provides a historical basis for examining vocational education outside traditional part-time apprenticeship schooling. Particularly useful for comparing full-time and part-time vocational education during the 1980s."
    },
    {
      "title": "Fachoberschulen in Hessen seit Schuljahr 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Historical dataset covering Fachoberschulen in Hesse from 1980/1981 onward. These institutions provide vocationally oriented upper-secondary education and pathways to higher education. Relevant for investigating educational progression, vocational qualifications, and institutional changes during the 1980s."
    },
    {
      "title": "Fachschulen in Hessen seit Schuljahr 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Official historical statistics on Fachschulen, institutions providing advanced vocational and professional education in Hesse. The time series begins in 1980/1981 and is relevant for analyzing continuing vocational education, advanced technical qualifications, and professional specialization throughout the 1980s."
    },
    {
      "title": "Hauptamtliche und hauptberufliche Lehrkräfte an allgemeinbildenden und beruflichen Schulen in Hessen seit 1980/1981",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/bildung",
      "justification": "Official historical dataset documenting full-time and principal-occupation teachers at general and vocational schools in Hesse since 1980/1981. Relevant for examining vocational education staffing, teaching capacity, and changes in educational resources during the 1980s. Researchers should distinguish vocational-school figures from general-school figures."
    },
    {
      "title": "Berufliche Schulen und Hochschulen in der Bundesrepublik Deutschland 1949–2001 – Historical Statistics (HISTAT)",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/project/details/d2441e8d20a05d8b31bb73351af34df7",
      "justification": "Historical education statistics compiled in connection with the German educational history data handbook by Peter Lundgreen and collaborators. Covers vocational schools across West Germany between 1949 and 2001, including the entire 1980s. Particularly useful for comparing vocational education trends in Hesse with those in other German federal states. Researchers should inspect the available tables to identify state-level breakdowns."
    },
    {
      "title": "Historical Statistics – German Education and Socioeconomic Development",
      "url_or_doi": "https://histat.safe-frankfurt.de/de/project/details/BCE3FBD7427EBA36273554764EC22DB1",
      "justification": "Historical statistical compilation based on German official statistics, including information on vocational schools and educational development. Covers historical periods encompassing the 1980s and offers context for studying vocational education within broader socioeconomic and educational developments. Potentially useful for comparative research, although the availability of Hesse-specific series should be verified."
    },
    {
      "title": "Bildung und Kultur – Fachserie 11, Reihe 2: Berufliches Schulwesen, Gesamtübersichten 1985",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/DEHeft_derivate_00056300/FS-11-2-1985.pdf",
      "justification": "Historical publication from Germany's Federal Statistical Office containing vocational education statistics for 1985. Includes tables identifying Hesse and other federal states. Valuable for examining vocational school participation and institutional characteristics during the mid-1980s. Provides an authoritative historical source for cross-state comparisons."
    },
    {
      "title": "Auszubildende und Prüfungen in Hessen – Historical Vocational Training Statistics",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/HEHeft_derivate_00001402/BII5_j11.pdf",
      "justification": "Official Hessian vocational training statistical report containing historical time-series data for 1980, 1985, 1990, and subsequent years. Includes apprentice numbers, newly concluded training contracts, prematurely terminated training relationships, and vocational examination results. Particularly useful for comparing the beginning and middle of the 1980s with later developments. The report contains historical statistical tables rather than a standalone machine-readable dataset."
    },
    {
      "title": "Daten zur Entwicklung von Bevölkerung und Wirtschaft in Hessen ab 1945 bis 2016",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/HEHeft_derivate_00007853/Z2_2j16.pdf",
      "justification": "Official historical statistical compilation covering economic and demographic developments in Hesse from 1945 to 2016. Includes vocational training indicators such as apprentice numbers and their distribution across economic training sectors, with historical observations covering the 1980s. Particularly useful for examining vocational education in relation to structural economic change and labor market developments."
    },
    {
      "title": "Berufsausbildung in Hessen 2004 – Historical Vocational School Enrollment Statistics",
      "url_or_doi": "https://starweb.hessen.de/cache/hessen/berufsausbildung_2004.pdf",
      "justification": "Hessian vocational education report containing retrospective statistics on vocational school enrollment by school type and gender. Includes observations for the academic years 1980/1981 and 1985/1986, making it especially relevant for studying vocational education during the 1980s. Historical figures originate from the Hessian Statistical Office's vocational school statistics."
    },
    {
      "title": "Hessisches Statistisches Informationssystem (HESIS)",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/datenbank-hesis",
      "justification": "Official statistical database maintained by the Hessian Statistical Office. Provides regional statistical information for Hesse, with filtering options ranging from the state level to districts and municipalities. Useful for investigating the availability of geographically disaggregated vocational education statistics. Historical coverage varies by indicator, so the availability of observations from the 1980s must be checked."
    },
    {
      "title": "Hessen Open Data – Statistik der beruflichen Schulen",
      "url_or_doi": "https://opendata.hessen.de/dataset/?groups=wissenschaft-und-technologie&tags=Statistik+der+beruflichen+Schulen",
      "justification": "Official Hessian open-data catalog filtered for vocational school statistics. Contains datasets concerning vocational education, including graduates and school leavers categorized by gender, qualifications, school year, and geographical level. Potentially useful for identifying downloadable educational statistics. The catalog does not establish that all listed datasets extend back to the 1980s, so historical coverage must be verified individually."
    }
  ]
}
